package com.fintrack.khmtomnenh.category.controller; import com.fintrack.khmtomnenh.category.dto.*; import com.fintrack.khmtomnenh.category.entity.*; import com.fintrack.khmtomnenh.category.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") @RequiredArgsConstructor public class CategoryController {private final CategoryService service; @GetMapping public List<Category> list(){return service.list();} @PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Category> create(@Valid @RequestBody CategoryDto d){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(d));} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public Category update(@PathVariable Long id,@Valid @RequestBody CategoryDto d){return service.update(id,d);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
